class Luhn:
    def __init__(self, card_num):
        self.card_num = card_num
        self.checksum = -1
        digits = card_num.replace(' ', '')
        if len(digits) <= 1 or not digits.isdecimal():
            return

        self.checksum = 0
        for index, digit in enumerate(reversed(digits)):
            num = int(digit)
            if index % 2 == 1:
                num *= 2
                if num > 9:
                    num -= 9
            self.checksum += num

    def valid(self):
        return self.checksum % 10 == 0

