from calendar import monthrange
from datetime import date


class MeetupDayException(ValueError):
    def __init__(self, message):
        super().__init__(message)
        self.message = message


def meetup(year, month, week, day_of_week):
    weekdays = ('Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday')
    if day_of_week not in weekdays:
        raise MeetupDayException('That day does not exist.')

    first_weekday, month_length = monthrange(year, month)
    first_match = 1 + (weekdays.index(day_of_week) - first_weekday) % 7
    days = range(first_match, month_length + 1, 7)
    if week == 'teenth':
        day = next(day for day in days if 13 <= day <= 19)
    elif week == 'last':
        day = days[-1]
    else:
        ordinals = ('first', 'second', 'third', 'fourth', 'fifth')
        if week not in ordinals:
            raise MeetupDayException('That day does not exist.')
        index = ordinals.index(week)
        if index >= len(days):
            raise MeetupDayException('That day does not exist.')
        day = days[index]
    return date(year, month, day)
